import numpy as np
for f in ['answer.xyz','xtb_answer.xyz']:
 xyz=[]
 for l in open(f).readlines()[2:]:
  a=l.split()
  if len(a)>3:xyz.append(np.array([float(x) for x in a[1:4]]))
 def sign(i,inds):
  v=[xyz[j]-xyz[i] for j in inds];return np.linalg.det(np.array([v[0]-v[3],v[1]-v[3],v[2]-v[3]]))
